// UI strings for vi + en, compiled by Paraglide JS from `messages/{locale}.json`.
// `src/paraglide/` is generated by `pnpm build`: never edit it.
import {
  defineCustomClientStrategy,
  getLocale,
  isLocale,
  locales,
  type Locale,
} from './paraglide/runtime.js';

/**
 * On the client, before the browser's languages: the locale the server rendered this page in
 * (`data-ssr-locale` on `<html>`, SSR build only). Without it, a request with no `Accept-Language`
 * (headless Chromium) renders in the base locale while the client picks `navigator.language`, and
 * hydration fails (React #418). The first `getLocale()` then stores it in the cookie, so both sides
 * agree from there on.
 */
interface HTMLLike {
  readonly dataset: Readonly<Record<string, string | undefined>>;
}

defineCustomClientStrategy('custom-ssr', {
  getLocale: () => {
    // No DOM types in this package: the client sees `document`, the server does not.
    const root = (globalThis as { document?: { documentElement: HTMLLike } }).document;
    const value = root?.documentElement.dataset['ssrLocale'];
    return value !== undefined && isLocale(value) ? value : undefined;
  },
  setLocale: () => undefined,
});

export { m } from './paraglide/messages.js';
export {
  baseLocale,
  getLocale,
  isLocale,
  locales,
  setLocale,
  type Locale,
} from './paraglide/runtime.js';

/** BCP 47 tags for each UI locale, for `Intl` and libraries that want a region (Astryx). */
export const localeTags = { vi: 'vi-VN', en: 'en-US' } as const satisfies Record<Locale, string>;

/** The active locale's BCP 47 tag. */
export const getLocaleTag = () => localeTags[getLocale()];

export const isSupportedLocale = (value: string): value is Locale =>
  (locales as ReadonlyArray<string>).includes(value);
